<?php
declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(404);exit;}$_SERVER['REQUEST_METHOD']='CLI';require_once __DIR__.'/../config/db.php';$c=db();$failed=false;
$checks=['overlapping periods'=>"SELECT COUNT(*) n FROM erp_accounting_periods a JOIN erp_accounting_periods b ON a.user_id=b.user_id AND a.id<b.id AND NOT(a.period_end<b.period_start OR a.period_start>b.period_end)",'missing snapshots'=>"SELECT COUNT(*) n FROM erp_accounting_periods p LEFT JOIN erp_accounting_period_snapshots s ON s.period_id=p.id WHERE s.id IS NULL",'snapshot tenant ownership'=>"SELECT COUNT(*) n FROM erp_accounting_period_snapshots s JOIN erp_accounting_periods p ON p.id=s.period_id WHERE s.user_id<>p.user_id",'lifecycle timestamps'=>"SELECT COUNT(*) n FROM erp_accounting_periods WHERE(status IN('REVIEWED','LOCKED','FILED') AND reviewed_at IS NULL)OR(status IN('LOCKED','FILED') AND locked_at IS NULL)OR(status='FILED' AND filed_at IS NULL)"];
foreach($checks as $label=>$sql){$n=(int)$c->query($sql)->fetch_assoc()['n'];if($n){$failed=true;fwrite(STDERR,"FAIL $label: $n mismatch(es)\n");}else echo "PASS $label reconciles\n";}$bad=0;foreach($c->query('SELECT id,snapshot_json,snapshot_sha256 FROM erp_accounting_period_snapshots') as $r)if(!hash_equals($r['snapshot_sha256'],hash('sha256',$r['snapshot_json'])))$bad++;if($bad){$failed=true;fwrite(STDERR,"FAIL snapshot hashes: $bad mismatch(es)\n");}else echo "PASS snapshot hashes reconcile\n";exit($failed?1:0);
